mapper.select:
SELECT id, name, start_time, end_time, status, create_time, update_time
FROM sms_seckill_activity
WHERE id = #{id}

SELECT id, activity_id, sku_id, product_id, seckill_price, seckill_stock,
       limit_count, status, create_time, update_time
FROM sms_seckill_sku
WHERE activity_id = #{activityId}
  AND sku_id = #{skuId}

mapper.update:
UPDATE sms_seckill_sku
SET seckill_stock = seckill_stock - #{quantity},
    update_time = NOW()
WHERE id = #{id}
  AND seckill_stock >= #{quantity}

mapper.select:
SELECT COUNT(*)
FROM oms_order
WHERE order_sn = #{orderSn}
